/bin/bash -lc "python3 - <<'PY'
import ast, hashlib, json, subprocess
from pathlib import Path
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
proposal=json.loads(Path('/workspace/proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
    kind=schema.get('type')
    if kind=='object':
        assert isinstance(value,dict),(path,'object')
        assert set(schema.get('required',[]))<=set(value),(path,'required')
        if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra')
        for k,v in value.items():
            if k in schema.get('properties',{}): validate(v,schema['properties'][k],path+'.'+k)
    elif kind=='array':
        assert isinstance(value,list),(path,'array')
        assert len(value)>=schema.get('minItems',0),(path,'minItems')
        for i,v in enumerate(value): validate(v,schema.get('items',{}),path+'['+str(i)+']')
    elif kind=='string':
        assert isinstance(value,str),(path,'string')
        assert len(value)>=schema.get('minLength',0),(path,'minLength')
    elif kind=='boolean': assert isinstance(value,bool),(path,'boolean')
    elif kind=='integer': assert isinstance(value,int) and not isinstance(value,bool),(path,'integer')
    elif kind=='number': assert isinstance(value,(float,int)) and not isinstance(value,bool),(path,'number')
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
validate(proposal['study'],runtime['study_schema'])
assert runtime['phase']=='propose'
assert Path('/workspace/proposal.json').is_file()
assert proposal['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert proposal['parent_trial'] in allowed
assert set(proposal['study']['evidence_refs'])<=allowed
assert all(x['parent_ref'] in allowed for x in proposal['study']['contrasts'])
variants=proposal['variants'];assert 1<=len(variants)<=4
assert any(v['role']=='candidate' for v in variants)
assert len({v['name'] for v in variants})==len(variants)
assert len({v['file'] for v in variants})==len(variants)
cells=set()
parent_source=Path('/workspace/history_g3_r0018_rank_event_route.py').read_bytes()
assert hashlib.sha256(parent_source).hexdigest()=='329ad18fa529c1c51cdde6fed251e58fb4bd02b98f379648317505fcb4cb6a39'
assert hashlib.sha256(Path('/workspace/baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
parent_ast=ast.parse(parent_source)
parent_cfg=ast.literal_eval(next(n.value for n in parent_ast.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
for v in variants:
    assert set(v)=={'name','file','role','config','note'}
    assert v['role'] in ('candidate','control')
    p=Path(v['file']);assert p.name==v['file'] and p.suffix=='.py'
    content=Path('/workspace',v['file']).read_text();module=ast.parse(content);compile(module,v['file'],'exec')
    cfg=ast.literal_eval(next(n.value for n in module.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
    assert cfg==v['config']
    assert set(cfg)==set(parent_cfg)|{'rank_feedback_identity','retain_position_route'}
    assert all(cfg[k]==val for k,val in parent_cfg.items())
    assert hashlib.sha256(content.encode()).hexdigest() in v['note']
    cells.add((cfg['rank_feedback_identity'],cfg['retain_position_route']))
assert cells=={(True,True),(True,False),(False,True),(False,False)}
industry={'unirank-method-infnet','unirank-method-unimixer','unirank-method-tokenmixer'}
assert industry<={a['knowledge_id'] for a in proposal['knowledge_assessments']}
for a in proposal['knowledge_assessments']:
    assert a['decision'] in ('used','considered','rejected','unresolved')
    assert set(a['variant_names'])<={v['name'] for v in variants}
    assert all(a[k] for k in ['rationale','transformed_mechanism','nearest_work_difference','falsifier'])
print('PASS: runtime study schema; proposal/phase/protocol; authorized lineage/evidence; all four factorial cells; standalone syntax/literal configurations; architecture-only changes; source hashes; immutable baseline/ancestor; industry knowledge assessments.')
print('DELIVERABLES: proposal.json, candidate.py, rank_collapsed_single.py, rank_resolved_duplicate.py, rank_collapsed_duplicate.py')
print('NOT EXECUTED: Torch model import, forward/backward/BF16, host training, validation scoring, withheld assessment. No such result is claimed.')
PY"

